loadstring(game:HttpGet("https://raw.githubusercontent.com/xpxking111111/Lilly-Snipes/main/source.lua"))()

local plrs = game:GetService("Players");
local lp = plrs.LocalPlayer;
local cam = workspace.CurrentCamera;

local mods = getloadedmodules();
local wm, wc;
for _, m in ipairs(mods) do
    if m.Name == "WeaponManager" then wm = m;
    elseif m.Name == "WeaponClient" then wc = m; end
    if wm and wc then break; end
end

local wmMod = require(wm);
local wcMod = require(wc);

local enabled = true;
local fov = 200;
local hitpart = "Head";

local function getTarget(origin)
    local closest, closestDist = nil, fov;
    for _, p in ipairs(plrs:GetPlayers()) do
        if p == lp then continue; end
        local char = p.Character;
        if not char then continue; end
        local hum = char:FindFirstChild("Humanoid");
        local hp = char:FindFirstChild(hitpart) or char:FindFirstChild("HumanoidRootPart");
        if not hum or hum.Health <= 0 or not hp then continue; end
        local sp, onScreen = cam:WorldToViewportPoint(hp.Position);
        if not onScreen then continue; end
        local dist = (Vector2.new(sp.X, sp.Y) - Vector2.new(cam.ViewportSize.X/2, cam.ViewportSize.Y/2)).Magnitude;
        if dist < closestDist then
            closestDist = dist;
            closest = hp;
        end
    end
    return closest;
end

local oldCast = wmMod.cast;
local oldRcast = wmMod.rcast;

local function aimDir(origin, default)
    if not enabled then return default; end
    local t = getTarget(origin);
    if not t then return default; end
    return (t.Position - origin).Unit;
end

wmMod.cast = newcclosure(function(origin, dir, ...)
    return oldCast(origin, aimDir(origin, dir), ...);
end);

wmMod.rcast = newcclosure(function(origin, dir, ...)
    return oldRcast(origin, aimDir(origin, dir), ...);
end);

game:GetService("UserInputService").InputBegan:Connect(function(inp, gp)
    if gp then return; end
    if inp.KeyCode == Enum.KeyCode.X then
        enabled = not enabled;
        print("silentaim: " .. tostring(enabled));
    end
end);

print("silentaim loaded X to toggle");
